    ["State"] = "Estado",
    ["Status"] = "Estado",
    ["Stop tracking %s as owed to %s?\n\nIt can no longer be traded. History is left alone - this only removes it from Loot to Trade."] = "\194\191Dejar de seguir %s como pendiente de entrega a %s?\n\nYa no se puede intercambiar. El historial no se toca: esto solo lo quita de \194\171Bot\195\173n por intercambiar\194\187.",
